contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public payable {
        require(amount > 0);
        require(loanToCollateral > 0);
        require(duration > 0);

        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration); if (__ESBMC_reverted()) return;
        bool active = c.isActive(reqID); if (__ESBMC_reverted()) return;

        assert(
            reqID == 0 &&
            active &&
            c.isActive(0)
        );
    }
}

